def get_max_triples(n):
    cnt0 = cnt1 = cnt2 = 0
    for i in range(1, n + 1):
        r = (i * i - i + 1) % 3
        if r == 0:
            cnt0 += 1
        elif r == 1:
            cnt1 += 1
        else:
            cnt2 += 1
    return (cnt0 * (cnt0 - 1) * (cnt0 - 2)) // 6 + \
           (cnt1 * (cnt1 - 1) * (cnt1 - 2)) // 6 + \
           (cnt2 * (cnt2 - 1) * (cnt2 - 2)) // 6 + \
           cnt0 * cnt1 * cnt2
